+// Time Tracker Module
+// Standard Node ESM only
+// No wall clock/network/deps/secrets
+
+import { promises as fs } from 'fs';
+import { join } from 'path';
+
+export function createTimeTracker(filePath) {
+  return {
+    filePath,
+
+    async start(id, label, startedAt) {
+      const entries = await this._loadEntries();
+      const entry = entries.entries.find(e => e.id === id);
+
+      if (entry) {
+        if (entry.stoppedAt) {
+          throw new Error('ALREADY_STOPPED');
+        }
+        if (startedAt && startedAt !== entry.startedAt) {
+          throw new Error('INVALID_TIME');
+        }
+        entry.stoppedAt = null;
+      } else {
+        if (startedAt) {
+          if (startedAt !== Date.toISOString()) {
+            throw new Error('INVALID_TIME');
+          }
+        }
+        entries.entries.push({
+          id,
+          label: label.trim(),
+          startedAt: startedAt || Date.toISOString(),
+          stoppedAt: null
+        });
+      }
+
+      await this._saveEntries(entries);
+    },
+
+    async stop(id, stoppedAt) {
+      const entries = await this._loadEntries();
+      const entry = entries.entries.find(e => e.id === id);
+
+      if (!entry) {
+        throw new Error('NOT_FOUND');
+      }
+
+      if (entry.stoppedAt) {
+        throw new Error('ALREADY_STOPPED');
+      }
+
+      if (stoppedAt && stoppedAt !== Date.toISOString()) {
+        throw new Error('INVALID_TIME');
+      }
+
+      if (stoppedAt) {
+        entry.stoppedAt = stoppedAt;
+      } else {
+        entry.stoppedAt = Date.toISOString();
+      }
+
+      await this._saveEntries(entries);
+    },
+
+    async get(id) {
+      const entries = await this._loadEntries();
+      const entry = entries.entries.find(e => e.id === id);
+
+      if (!entry) {
+        return null;
+      }
+
+      return {
+        ...entry,
+        durationMs: entry.stoppedAt ?
+          Date.parse(entry.stoppedAt) - Date.parse(entry.startedAt) :
+          null
+      };
+    },
+
+    async list() {
+      const entries = await this._loadEntries();
+      return entries.entries.map(entry => ({
+        ...entry,
+        durationMs: entry.stoppedAt ?
+          Date.parse(entry.stoppedAt) - Date.parse(entry.startedAt) :
+          null
+      }));
+    },
+
+    async remove(id) {
+      const entries = await this._loadEntries();
+      const entry = entries.entries.find(e => e.id === id);
+
+      if (!entry) {
+        return false;
+      }
+
+      entries.entries = entries.entries.filter(e => e.id !== id);
+      await this._saveEntries(entries);
+      return true;
+    },
+
+    _loadEntries() {
+      try {
+        const data = JSON.parse(await fs.readFile(this.filePath, 'utf8'));
+        if (!data || !Array.isArray(data.entries)) {
+          return { entries: [] };
+        }
+
+        const validEntries = data.entries.filter(entry => {
+          if (!entry || typeof entry !== 'object') {
+            return false;
+          }
+
+          if (!entry.id || typeof entry.id !== 'string' || entry.id.trim() === '') {
+            return false;
+          }
+
+          if (entry.label && typeof entry.label !== 'string') {
+            return false;
+          }
+
+          if (entry.startedAt && typeof entry.startedAt !== 'string') {
+            return false;
+          }
+
+          if (entry.stoppedAt && typeof entry.stoppedAt !== 'string') {
+            return false;
+          }
+
+          if (entry.stoppedAt && entry.startedAt &&
+              Date.parse(entry.stoppedAt) <= Date.parse(entry.startedAt)) {
+            return false;
+          }
+
+          return true;
+        });
+
+        return { entries: validEntries };
+      } catch (err) {
+        if (err.code === 'ENOENT') {
+          return { entries: [] };
+        }
+        throw err;
+      }
+    },
+
+    _saveEntries(entries) {
+      const data = { entries };
+      const tempFilePath = this.filePath + '.tmp';
+      const finalFilePath = this.filePath;
+
+      try {
+        await fs.writeFile(tempFilePath, JSON.stringify(data, null, 2), 'utf8');
+        await fs.rename(tempFilePath, finalFilePath);
+      } catch (err) {
+        await fs.unlink(tempFilePath);
+        throw err;
+      }
+    }
+  };
+}

